import QRCode from "qrcode";

import { cn } from "@/lib/utils";

interface QrCodeProps {
  value: string;
  /** Accessible label (the QR itself is an image). */
  label: string;
  className?: string;
}

/**
 * Server-rendered QR code (inline SVG, no client JS). Used on the web card
 * (token) and on the poster (join link).
 */
export async function QrCode({ value, label, className }: QrCodeProps) {
  // The SVG is generated by the qrcode library from our own value — no user HTML.
  const svg = await QRCode.toString(value, {
    type: "svg",
    errorCorrectionLevel: "M",
    margin: 2,
    color: { dark: "#000000", light: "#ffffff" },
  });

  return (
    <div
      role="img"
      aria-label={label}
      className={cn("aspect-square w-full bg-white [&>svg]:size-full", className)}
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
